package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;
import com.ruoyi.medical.contracts.*;
import java.util.*;
final class DocumentScenarioInputs {
 private DocumentScenarioInputs(){}
 static List<DatasetProtocol.EvidenceRef> require(JsonNode fixed,TaskNodeProductionAuthority.Verified p,List<TaskNodeInputProtocol.SourceSelection> sources)throws Exception{
  if(fixed==null)return List.of();if(RegistrationLifecycleSchema.supportsKind(fixed.required("selection").required("scenario_kind").asText()))return lifecycle(fixed,p,sources);if(MultimodalQaSchema.KIND.equals(fixed.required("selection").required("scenario_kind").asText()))return multimodal(fixed,p,sources);if(ClinicalEvaluationSchema.KIND.equals(fixed.required("selection").required("scenario_kind").asText()))return clinical(fixed,p,sources);if(InstructionsLabelSchema.KIND.equals(fixed.required("selection").required("scenario_kind").asText()))return instructions(fixed,p,sources);if(NonclinicalPrinciplesRiskSchema.KIND.equals(fixed.required("selection").required("scenario_kind").asText()))return nonclinical(fixed,p,sources);if(RegistrationDossierSchema.KIND.equals(fixed.required("selection").required("scenario_kind").asText()))return dossier(fixed,p,sources);if(ProductTechnicalRequirementSchema.KIND.equals(fixed.required("selection").required("scenario_kind").asText()))return technical(fixed,p,sources);if(MarketAnalysisScenarioSchema.KIND.equals(fixed.required("selection").required("scenario_kind").asText()))return market(fixed,p,sources);if(TranslationScenarioSchema.KIND.equals(fixed.required("selection").required("scenario_kind").asText()))return translation(fixed,p,sources);var selection=new ReportScenarioSchema().read(fixed.required("selection"));var refs=new LinkedHashSet<DatasetProtocol.EvidenceRef>();
  for(var item:selection.inputs()){var ref=item.evidence();if(!p.tenantId().equals(ref.tenantId())||!p.projectId().equals(ref.projectId())||sources.stream().filter(s->s.sourceVersion().equals(ref.sourceVersion())&&s.parseVersion().equals(ref.parseVersion())&&s.approvalRevision().equals(ref.approvalRevision())&&s.rightsRevision().equals(item.rightsRevision())).count()!=1)throw new TenantAccessException(ErrorCode.ACCESS_DENIED);refs.add(ref);}return List.copyOf(refs);
 }
 static List<DatasetProtocol.EvidenceRef> translation(JsonNode fixed,TaskNodeProductionAuthority.Verified p,List<TaskNodeInputProtocol.SourceSelection> sources)throws Exception{
  var s=new TranslationScenarioSchema().read(fixed.required("selection"));var refs=new LinkedHashSet<DatasetProtocol.EvidenceRef>();for(var item:s.segments()){var r=item.evidence();if(!p.tenantId().equals(r.tenantId())||!p.projectId().equals(r.projectId())||sources.stream().filter(x->x.sourceVersion().equals(r.sourceVersion())&&x.parseVersion().equals(r.parseVersion())&&x.approvalRevision().equals(r.approvalRevision())&&x.rightsRevision().equals(item.rightsRevision())).count()!=1)throw new TenantAccessException(ErrorCode.ACCESS_DENIED);refs.add(r);}return List.copyOf(refs);
 }
 static List<DatasetProtocol.EvidenceRef> market(JsonNode fixed,TaskNodeProductionAuthority.Verified p,List<TaskNodeInputProtocol.SourceSelection> sources)throws Exception{
  var s=new MarketAnalysisScenarioSchema().read(fixed.required("selection"));var refs=new LinkedHashSet<DatasetProtocol.EvidenceRef>();
  for(var i:s.inputs()){marketSource(p,sources,i.evidence(),i.rightsRevision());refs.add(i.evidence());}for(var c:s.context()){marketSource(p,sources,c.evidence(),c.rightsRevision());refs.add(c.evidence());}return List.copyOf(refs);
 }
 static List<DatasetProtocol.EvidenceRef> technical(JsonNode fixed,TaskNodeProductionAuthority.Verified p,List<TaskNodeInputProtocol.SourceSelection> sources)throws Exception{
  var selection=new ProductTechnicalRequirementSchema().read(fixed.required("selection"));var refs=new LinkedHashSet<DatasetProtocol.EvidenceRef>();for(var item:selection.sources()){marketSource(p,sources,item.evidence(),item.rightsRevision());refs.add(item.evidence());}return List.copyOf(refs);
 }
 static List<DatasetProtocol.EvidenceRef> dossier(JsonNode fixed,TaskNodeProductionAuthority.Verified p,List<TaskNodeInputProtocol.SourceSelection> sources)throws Exception{
  var selection=new RegistrationDossierSchema().read(fixed.required("selection"));var refs=new LinkedHashSet<DatasetProtocol.EvidenceRef>();for(var item:selection.sources()){marketSource(p,sources,item.evidence(),item.rightsRevision());refs.add(item.evidence());}return List.copyOf(refs);
 }
 static List<DatasetProtocol.EvidenceRef> nonclinical(JsonNode fixed,TaskNodeProductionAuthority.Verified p,List<TaskNodeInputProtocol.SourceSelection> sources)throws Exception{
  var selection=new NonclinicalPrinciplesRiskSchema().read(fixed.required("selection"));var refs=new LinkedHashSet<DatasetProtocol.EvidenceRef>();for(var item:selection.sources()){marketSource(p,sources,item.evidence(),item.rightsRevision());refs.add(item.evidence());}return List.copyOf(refs);
 }
 static List<DatasetProtocol.EvidenceRef> clinical(JsonNode fixed,TaskNodeProductionAuthority.Verified p,List<TaskNodeInputProtocol.SourceSelection> sources)throws Exception{
  var selection=new ClinicalEvaluationSchema().read(fixed.required("selection"));var refs=new LinkedHashSet<DatasetProtocol.EvidenceRef>();for(var item:selection.sources()){marketSource(p,sources,item.evidence(),item.rightsRevision());refs.add(item.evidence());}return List.copyOf(refs);
 } static List<DatasetProtocol.EvidenceRef> instructions(JsonNode fixed,TaskNodeProductionAuthority.Verified p,List<TaskNodeInputProtocol.SourceSelection> sources)throws Exception{
  var selection=new InstructionsLabelSchema().read(fixed.required("selection"));var refs=new LinkedHashSet<DatasetProtocol.EvidenceRef>();for(var item:selection.sources()){marketSource(p,sources,item.evidence(),item.rightsRevision());refs.add(item.evidence());}return List.copyOf(refs);
 }
 static List<DatasetProtocol.EvidenceRef> multimodal(JsonNode fixed,TaskNodeProductionAuthority.Verified p,List<TaskNodeInputProtocol.SourceSelection> sources)throws Exception{var s=new MultimodalQaSchema().read(fixed.required("selection"));var sections=new HashSet<String>();for(var section:p.replay().content().required("plan").required("content").required("sections"))sections.add(section.required("section_id").asText());for(var q:s.questions())if(!sections.contains(q.sectionId()))throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);var refs=new LinkedHashSet<DatasetProtocol.EvidenceRef>();for(var item:s.inputs()){marketSource(p,sources,item.evidence(),item.rightsRevision());refs.add(item.evidence());}return List.copyOf(refs);}
 static List<DatasetProtocol.EvidenceRef> lifecycle(JsonNode fixed,TaskNodeProductionAuthority.Verified p,List<TaskNodeInputProtocol.SourceSelection> sources)throws Exception{var selection=new RegistrationLifecycleSchema().read(fixed.required("selection"));var sections=new HashSet<String>();for(var section:p.replay().content().required("plan").required("content").required("sections"))sections.add(section.required("section_id").asText());if(!sections.containsAll(selection.sectionIds()))throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);var refs=new LinkedHashSet<DatasetProtocol.EvidenceRef>();for(var item:selection.sources()){marketSource(p,sources,item.evidence(),item.rightsRevision());refs.add(item.evidence());}return List.copyOf(refs);}
 private static void marketSource(TaskNodeProductionAuthority.Verified p,List<TaskNodeInputProtocol.SourceSelection> sources,DatasetProtocol.EvidenceRef r,String rights){if(!p.tenantId().equals(r.tenantId())||!p.projectId().equals(r.projectId())||sources.stream().filter(x->x.sourceVersion().equals(r.sourceVersion())&&x.parseVersion().equals(r.parseVersion())&&x.approvalRevision().equals(r.approvalRevision())&&x.rightsRevision().equals(rights)).count()!=1)throw new TenantAccessException(ErrorCode.ACCESS_DENIED);}
}
